    UUT.prog = 2048';

    // state 0
    UUT.imem_ready = 1'b0;
    UUT.dmem_rdata = 32'b00000000000000000000000000000000;
    UUT.dmem_ready = 1'b0;
  end
  always @(posedge clock) begin
    // state 1
    if (cycle == 0) begin
      UUT.imem_ready <= 1'b1;
      UUT.dmem_rdata <= 32'b00000000000000000000000000000000;
      UUT.dmem_ready <= 1'b0;
    end

    // state 2
    if (cycle == 1) begin
      UUT.imem_ready <= 1'b1;
      UUT.dmem_rdata <= 32'b00000000000000000000000000000000;
      UUT.dmem_ready <= 1'b0;
    end

    // state 3
    if (cycle == 2) begin
      UUT.imem_ready <= 1'b1;
      UUT.dmem_rdata <= 32'b00000000000000000000000000000000;
      UUT.dmem_ready <= 1'b0;
    end

    // state 4
    if (cycle == 3) begin
      UUT.imem_ready <= 1'b1;
      UUT.dmem_rdata <= 32'b01111111111111111111111111111111;
      UUT.dmem_ready <= 1'b1;
    end

    // state 5
    if (cycle == 4) begin
      UUT.imem_ready <= 1'b0;
      UUT.dmem_rdata <= 32'b01111111111111111111111111111111;
      UUT.dmem_ready <= 1'b1;
    end

    // state 6
    if (cycle == 5) begin
      UUT.imem_ready <= 1'b1;
      UUT.dmem_rdata <= 32'b11111111111111111111111111111111;
      UUT.dmem_ready <= 1'b0;
    end

    // state 7
    if (cycle == 6) begin
      UUT.imem_ready <= 1'b1;
      UUT.dmem_rdata <= 32'b11111111111111111111111111111111;
      UUT.dmem_ready <= 1'b0;
    end

    // state 8
    if (cycle == 7) begin
      UUT.imem_ready <= 1'b1;
      UUT.dmem_rdata <= 32'b11111111111111111111111111111111;
      UUT.dmem_ready <= 1'b1;
    end

    // state 9
    if (cycle == 8) begin
      UUT.imem_ready <= 1'b0;
      UUT.dmem_rdata <= 32'b00000000000000000000000000000000;
      UUT.dmem_ready <= 1'b1;
    end

    genclock <= cycle < 9;
    cycle <= cycle + 1;
  end
endmodule
